<template><section class="section"><div class="container-page"><h1 class="text-4xl text-neutral-900">Properties for Sale</h1><p class="mt-3 text-neutral-600">Search verified Lexshield land and estate opportunities.</p><form class="mt-8 flex max-w-xl gap-2" @submit.prevent="search = draft"><input v-model="draft" class="input" type="search" placeholder="Search by estate, city, or state" aria-label="Search properties" /><button class="btn-primary">Search</button></form><div v-if="pending" class="mt-8">Loading…</div><div v-else-if="properties?.length" class="mt-8 grid gap-6 md:grid-cols-2 lg:grid-cols-3"><PropertyCard v-for="property in properties" :key="property.id" :property="property" /></div><p v-else class="mt-8 text-neutral-600">No matching properties found.</p></div></section></template>
<script setup lang="ts">const search=ref(''); const draft=ref(''); const {list}=useProperties(); const {data:properties,pending}=useAsyncData('property-catalogue',()=>list({search:search.value}),{watch:[search]}); useSeoMeta({title:'Properties for Sale | Lexshield Properties',description:'Browse verified land and estate properties from Lexshield Properties.'})</script>
